import arrtForm from './components/extemal/arrtForm'
import {getExtCodeList, globalattrSearch, globalattrDel} from "@/api/system/extemal";

export default {
  components: {
    arrtForm
  },
  data() {
    return {
      selectionList: [],
      cmdbCiIdList: [],
      cmdbAttrCodeList: [],
      i6000AttrCodeList: [],
      searchForm: {
        current: 1,
        size: 20,
        extCode: undefined,
        extId: undefined,
        extName: undefined,
        extPid: undefined,
      },
      total: 0,

      tableData: [],
      tableHeight: undefined,
      tableLoading: false,
      // 弹窗
      showForm: false,
      showType: '',
      arrtId: '',

      extCodeList:null,
    }
  },
  mounted() {
    this.setPageContentHeight();
    this.setTableHeight();
    this.getDict();
    this.getList();
  },
  methods: {
    selectionChange(selection) {
      //点击选择事件
      this.selectionList = selection.map(item => item.id);
    },
    changeStatus(row) {
      if (row.i6000OriType === '1') {
        return "手工录入"
      } else if (row.i6000OriType === '2') {
        return "枚举数据"
      } else if (row.i6000OriType === '3') {
        return "配置类型"
      } else if (row.i6000OriType === '4') {
        return "外部数据"
      }
    },
    showDictLable(code, dictList) {
      //字典回显
      if (dictList != null && code !== '') {
        let items = dictList.filter(item => item.dictKey == code);
        if (items != null && items.length > 0) {
          return items[0].dictValue;
        }
      }
      return code;
    },
    handleQuery() {
      this.searchForm.current = 1;
      this.getList();
    },
    handleReset() {
      this.searchForm.extCode = undefined;
      this.searchForm.extId = undefined;
      this.searchForm.extName = undefined;
      this.searchForm.extPid = undefined;

      this.getList();
    },
    getDict() {
      getExtCodeList().then(res => {
        this.extCodeList = res.data;
      });
    },
    // 设置表格高度
    setTableHeight() {
      let bodyBox = document.getElementsByClassName('page_body');
      this.tableHeight = (bodyBox[0].offsetHeight - 120) + 'px'
    },
    getList() {
      this.tableLoading = true;
      globalattrSearch(this.searchForm).then(res => {
        this.tableData = res.data.records;
        this.total = res.data.total;
        this.tableLoading = false
      }).catch(() => {
        this.tableLoading = false
      })
    },
    // 删除
    delArrt() {
      this.$confirm('确定是否删除?', '提示', {
        confirmButtonText: '确定',
        cancelButtonText: '取消',
        type: 'warning'
      }).then(() => {
        globalattrDel({ids: this.selectionList.join(',')}).then(res => {
          this.$message({
            type: 'success',
            message: '删除成功！'
          });
          this.getList()
        })
      })
    },
    // 编辑
    editArrt(row) {
      this.showType = '修改'
      this.arrtId = row.id
      this.showForm = true
    },
    saveGlobalArrt() {
      this.showForm = false
      this.getList()
    }
  }
}
